(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const w1y = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const w2x = Math.sin(w1x*0.025+t*0.4)*6 + Math.cos(w1y*0.02-t*0.35)*5;
  const w2y = Math.cos(w1y*0.022+t*0.38)*6 + Math.sin(w1x*0.018-t*0.42)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.0, 0.9],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.7, 1.1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 0.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 1.2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 0.7],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 1.9, 1.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.07, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.1, 1.6, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    cS += Math.sin(d*f*1.3 - t*sp*0.4 + 2.8) * w * 0.5;
  }
  const nS = 8;
  const act = aS/nS, inh = iS/nS, cross = cS/nS;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
  const bg2 = (Math.sin(sx*0.06+sy*0.04-t*0.9) + Math.cos(sx*0.045-sy*0.055+t*1.3))/2;
  const turb = Math.sin(sx*0.11+t*2.3)*Math.sin(sy*0.13-t*1.8)*Math.sin((sx-sy)*0.08+t*1.6);
  const bg = bg1*0.5 + bg2*0.3 + turb*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.035+ang*5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2+t*0.8)*Math.cos(ang*7-dist*0.02+t*2.2);
  const spiral = (sp1+sp2)*0.35 + sp3*0.15;
  const ring = Math.sin(dist*0.08-t*1.2)*Math.exp(-dist*0.003)*0.4;
  const cellA = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14) + Math.sin((sx+sy)*0.09+t)*0.5)*1.6);
  const cellB = Math.tanh((Math.sin(sx*0.08+1.2)*Math.cos(sy*0.11+0.8) + Math.sin((sx-sy)*0.07-t*0.7)*0.4)*1.4);
  const cell = (cellA*0.6+cellB*0.4)*0.25;
  const rd1 = Math.tanh((act - inh*0.65 + bg*0.35 + spiral + ring)*2.0);
  const rd2 = Math.tanh((cross*0.8 - act*0.3 + inh*0.5 + bg2*0.4 - ring)*1.8);
  const coupled = Math.tanh((rd1*0.7 + rd2*0.3 + cell)*1.5);
  const pulse = 0.92 + Math.sin(t*0.8)*0.08;
  const blend = coupled * pulse;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[10,35,82],[12,65,105],[18,110,130],
    [35,155,145],[120,185,140],[195,200,90],
    [225,165,60],[215,110,55],[180,60,60],
    [130,30,55],[70,15,48],[30,10,40],[5,12,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const r1 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g1 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b1 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82 + Math.sin(Math.abs(coupled)*Math.PI)*0.18;
  const edge = Math.abs(coupled)>0.65 ? 1.12 + (Math.abs(coupled)-0.65)*0.5 : 1.0;
  const glow = Math.max(0, 1-Math.abs(coupled)*1.2)*0.15;
  const rd2c = rd2*0.5+0.5;
  const shift = (rd2c-0.5)*12;
  return [
    Math.min(255, Math.max(0, ((r1+shift)*lum*edge + glow*40)|0)),
    Math.min(255, Math.max(0, ((g1-shift*0.3)*lum*edge + glow*60)|0)),
    Math.min(255, Math.max(0, ((b1+shift*0.6)*lum*edge + glow*80)|0))
  ];
}
